function UICommonFilterAlignCell:RefreshSelectState(isSelect)
    KTool.SetActive(self.Checkmark.gameObject, isSelect)

    if self.styleType then
        local t = {
            [StyleType.Black] = {1, 3},
            [StyleType.White] = {2, 4}
        }
        local status = 3
        if self.styleType == StyleType.Black then
            status = isSelect and 3 or 1
        else
            status = isSelect and 4 or 2
        end
        self.Text.Status = status
        self.Image.Status = status
    else
        -- self.Image.Status = isSelect and 3 or 1
        -- self.Text.Status = isSelect and 3 or 1
        self.Text.color = XLuaUtils.HexToColor(isSelect and "f9f9f9" or "c9c9c9")
    end
