end

function UICommonFilterAlignCell:RefreshAlignImage(asc)
    if asc ~= nil then
        local z = asc and 0 or 180
        self.Image.transform.localEulerAngles = Vector3.New(0, 0, z)
        CfUtils.SetActive(self.Image, true)
    else
        CfUtils.SetActive(self.Image, false)
    end
end

